const founderData=[{id:"jamsetji-tata",founder:"Jamsetji Tata",brand:"Tata Group",foundingYear:1868,city:"Mumbai",region:"Maharashtra",industry:"Conglomerate",founderStory:"Regarded as the 'Father of Indian Industry', Jamsetji Tata began his entrepreneurial journey with a trading company in 1868 and later set up the Empress Mill in Nagpur in 1874. He laid the foundation for India's industrialization by conceptualizing the Taj Mahal Hotel, the Indian Institute of Science, and the Tata Iron and Steel Company (now Tata Steel), fundamentally shaping modern India's economy.",milestones:[{year:1868,title:"Trading Company Founded",description:"Jamsetji started a trading company in Bombay with a capital of ₹21,000."},{year:1874,title:"Empress Mill",description:"Established the Central India Spinning, Weaving, and Manufacturing Company in Nagpur."},{year:1903,title:"Taj Mahal Palace Hotel",description:"The iconic Taj Mahal Hotel was opened in Mumbai, becoming the first building in the city to use electricity."}],sources:[{title:"Tata Group Official History",url:"https://www.tata.com/about-us/tata-group-history"},{title:"Biography of Jamsetji Tata",url:"#"}]},{id:"dhirubhai-ambani",founder:"Dhirubhai Ambani",brand:"Reliance Industries",foundingYear:1958,city:"Mumbai",region:"Maharashtra",industry:"Conglomerate",founderStory:"Dhirubhai Ambani started his business career trading spices and yarn in Aden, Yemen before returning to India to found Reliance Commercial Corporation in 1958. Through aggressive backwards integration and pioneering the equity cult in India by taking his company public in 1977, he built Reliance into a petrochemicals and textiles giant.",milestones:[{year:1958,title:"Reliance Commercial Corporation",description:"Started trading spices and polyester yarn in Masjid Bunder, Mumbai."},{year:1966,title:"Naroda Mill",description:"Set up a textile mill in Naroda, Gujarat, launching the brand 'Vimal'."},{year:1977,title:"IPO & Equity Cult",description:"Reliance went public, introducing thousands of middle-class Indians to the stock market."}],sources:[{title:"Reliance Industries Heritage",url:"https://www.ril.com/"}]},{id:"nr-narayana-murthy",founder:"N. R. Narayana Murthy (and co-founders)",brand:"Infosys",foundingYear:1981,city:"Pune",region:"Maharashtra",industry:"Technology",founderStory:"Founded by N. R. Narayana Murthy and six other software engineers (including Nandan Nilekani and S. Gopalakrishnan) in Pune with a capital of just $250 (Rs 10,000) borrowed from Murthy's wife, Sudha Murty. Infosys pioneered the Global Delivery Model for IT services and became the first Indian company listed on the NASDAQ.",milestones:[{year:1981,title:"Infosys Consultants Founded",description:"Established in Pune before moving its headquarters to Bengaluru in 1983."},{year:1993,title:"Indian IPO",description:"Infosys went public in India, sharing wealth with employees through ESOPs."},{year:1999,title:"NASDAQ Listing",description:"Became the first Indian-registered company to be listed on NASDAQ."}],sources:[{title:"Infosys Company History",url:"https://www.infosys.com/about/history.html"}]},{id:"karsanbhai-patel",founder:"Karsanbhai Patel",brand:"Nirma",foundingYear:1969,city:"Ahmedabad",region:"Gujarat",industry:"Consumer Goods",founderStory:"While working as a lab technician in the geology department of the Gujarat government, Karsanbhai Patel started manufacturing phosphate-free synthetic detergent powder in the backyard of his house. Selling it door-to-door on his bicycle at a fraction of the cost of multinational brands, Nirma democratized detergent for the Indian middle class.",milestones:[{year:1969,title:"Backyard Production",description:"Started mixing detergent by hand and selling it on a bicycle."},{year:1985,title:"Market Leader",description:"Nirma overtook Surf to become the top-selling detergent in India."},{year:2004,title:"Diversification",description:"Expanded into cement, soda ash, and healthcare."}],sources:[{title:"Nirma Corporate Story",url:"https://www.nirma.co.in/our-story/"}]},{id:"kiran-mazumdar-shaw",founder:"Kiran Mazumdar-Shaw",brand:"Biocon",foundingYear:1978,city:"Bengaluru",region:"Karnataka",industry:"Healthcare",founderStory:"Unable to find a job as a master brewer in India due to gender bias, Kiran Mazumdar-Shaw started Biocon out of the garage of her rented house in Bengaluru with ₹10,000. It began as a joint venture extracting enzymes for brewing and evolved into India's premier biopharmaceutical enterprise.",milestones:[{year:1978,title:"Garage Startup",description:"Started extracting papain and isinglass for the brewing industry."},{year:1989,title:"US FDA Approval",description:"Became the first Indian company to receive US FDA funding for proprietary technologies."},{year:2004,title:"IPO & Evolution",description:"Listed on the stock exchange as it pivoted heavily into biopharmaceuticals and insulin."}],sources:[{title:"Biocon Heritage",url:"https://www.biocon.com/about-us/heritage/"}]},{id:"dr-verghese-kurien",founder:"Dr. Verghese Kurien (and Tribhuvandas Patel)",brand:"Amul",foundingYear:1946,city:"Anand",region:"Gujarat",industry:"Food & Beverage",founderStory:"While Tribhuvandas Patel founded the cooperative to stop the exploitation of marginal milk producers, it was Dr. Verghese Kurien who managed and scaled it. Known as the 'Father of the White Revolution', Kurien transformed Amul into a global cooperative model that made India the world's largest milk producer.",milestones:[{year:1946,title:"Kaira District Co-operative",description:"Formed in response to unfair trade practices by milk cartels."},{year:1955,title:"Buffalo Milk Powder",description:"Pioneered the technology to produce milk powder from buffalo milk instead of cow milk."},{year:1970,title:"Operation Flood",description:"Sparked the White Revolution, replicating the Anand pattern across India."}],sources:[{title:"Amul Origin Story",url:"https://amul.com/m/about-us"}]}];document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("founder-grid"),n=document.getElementById("search-input"),t=document.getElementById("industry-filter"),a=document.getElementById("region-filter"),i=document.getElementById("no-results"),r=document.getElementById("founder-details"),o=document.getElementById("details-placeholder"),s=[...new Set(founderData.map(e=>e.industry))].sort(),d=[...new Set(founderData.map(e=>e.region))].sort();function l(){const s=n.value.toLowerCase(),d=t.value,l=a.value,c=founderData.filter(e=>{const n=e.founder.toLowerCase().includes(s)||e.brand.toLowerCase().includes(s),t="all"===d||e.industry===d,a="all"===l||e.region===l;return n&&t&&a});e.innerHTML="",0===c.length?i.classList.remove("hidden"):(i.classList.add("hidden"),c.forEach(n=>{const t=document.createElement("div");t.className="founder-card",t.setAttribute("data-id",n.id),t.innerHTML=`\n                    <h3 class="fc-name">${n.founder}</h3>\n                    <p class="fc-brand">${n.brand}</p>\n                    \n                    <div class="fc-meta">\n                        <div><span>📍</span> ${n.city}, ${n.region}</div>\n                        <div><span>📅</span> Founded: ${n.foundingYear}</div>\n                        <div><span>🏷️</span> ${n.industry}</div>\n                    </div>\n                    \n                    <div class="fc-action">View Details &rarr;</div>\n                `,t.addEventListener("click",()=>{document.querySelectorAll(".founder-card").forEach(e=>e.classList.remove("active")),t.classList.add("active"),function(e){o.classList.add("hidden"),r.classList.remove("hidden");let n=e.milestones.map(e=>`\n            <div class="timeline-item">\n                <div class="timeline-dot"></div>\n                <div class="timeline-year">${e.year}</div>\n                <h4 class="timeline-title">${e.title}</h4>\n                <p class="timeline-desc">${e.description}</p>\n            </div>\n        `).join(""),t=e.sources.map(e=>`\n            <a href="${e.url}" target="_blank" rel="noopener noreferrer" class="source-item">${e.title}</a>\n        `).join("");r.innerHTML=`\n            <div class="fd-header">\n                <h2 class="fd-name">${e.founder}</h2>\n                <div class="fd-brand-container">\n                    <span class="fd-brand">${e.brand}</span>\n                    <span class="fd-industry-tag">${e.industry}</span>\n                </div>\n                <div class="fd-meta">\n                    <span>📍 ${e.city}, ${e.region}</span>\n                    <span>📅 Established: ${e.foundingYear}</span>\n                </div>\n            </div>\n            \n            <h3 class="fd-section-title">The Founder's Story</h3>\n            <p class="fd-story">${e.founderStory}</p>\n            \n            <h3 class="fd-section-title">Timeline & Milestones</h3>\n            <div class="timeline-container">\n                <div class="timeline">\n                    ${n}\n                </div>\n            </div>\n            \n            <h3 class="fd-section-title">Verified Sources</h3>\n            <div class="sources-container">\n                ${t}\n            </div>\n        `}(n)}),e.appendChild(t)}))}s.forEach(e=>{const n=document.createElement("option");n.value=e,n.textContent=e,t.appendChild(n)}),d.forEach(e=>{const n=document.createElement("option");n.value=e,n.textContent=e,a.appendChild(n)}),n.addEventListener("input",l),t.addEventListener("change",l),a.addEventListener("change",l),l()});